// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doAnswer;

import java.util.Collections;
import java.util.Optional;

import org.eclipse.kura.KuraException;
import org.junit.Test;

public class EnforcementDigestPruningTest extends AbstractEnforcementTest {

    @Test
    public void digestOfContainerRemovedWhileUnmonitoredIsPruned() throws KuraException {
        givenDigestRegisteredBy(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainer(OTHER_CONTAINER_ID, IMAGE_DIGEST);

        whenEnforcementStarts();

        thenContainerWasDeleted(OTHER_CONTAINER_ID);
        thenDigestIsNotRegistered(IMAGE_DIGEST);
    }

    @Test
    public void digestOfExistingContainerIsKept() throws KuraException {
        givenDigestRegisteredBy(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenRunningContainer(OTHER_CONTAINER_ID, IMAGE_DIGEST);

        whenEnforcementStarts();

        thenContainerWasNotDeleted(OTHER_CONTAINER_ID);
        thenDigestIsRegistered(IMAGE_DIGEST);
    }

    @Test
    public void digestRegisteredWhileContainersAreListedIsKept() {
        givenContainerRegisteredWhileContainersAreListed(THIRD_CONTAINER_ID, OTHER_IMAGE_DIGEST);

        whenEnforcementStarts();

        thenDigestIsRegistered(OTHER_IMAGE_DIGEST);
    }

    private void givenContainerRegisteredWhileContainersAreListed(String containerId, String digest) {
        doAnswer(invocation -> {
            this.enforcement.register(containerId, Optional.of(digest));
            return Collections.emptyList();
        }).when(this.target).listContainerDescriptors();
    }

    private void thenDigestIsRegistered(String digest) {
        assertTrue(this.enforcement.getRegisteredDigests().contains(digest));
    }

    private void thenDigestIsNotRegistered(String digest) {
        assertFalse(this.enforcement.getRegisteredDigests().contains(digest));
    }
}
